-- =====================================================
-- SUMMARY OF SUSPENDED SERVICES
-- =====================================================
SELECT 
    'Successfully suspended ' || COUNT(*) || ' Cortex Search services across ' || COUNT(DISTINCT database_name) || ' databases' as summary
FROM (
    SELECT DISTINCT 
        database_name, 
        schema_name, 
        service_name
    FROM SNOWFLAKE.ACCOUNT_USAGE.CORTEX_SEARCH_DAILY_USAGE_HISTORY 
    WHERE usage_date >= CURRENT_DATE - 3
);

